import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"개발자 가이드","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 아키텍처 및 개발 워크플로","slug":"_1-아키텍처-및-개발-워크플로","link":"#_1-아키텍처-및-개발-워크플로","children":[]},{"level":2,"title":"2. 플러그인 SDK API 레퍼런스","slug":"_2-플러그인-sdk-api-레퍼런스","link":"#_2-플러그인-sdk-api-레퍼런스","children":[]}],"relativePath":"ko-KR/dev-guide/index.md","filePath":"ko-KR/dev-guide/index.md","lastUpdated":1791112464000}`),a={name:`ko-KR/dev-guide/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="개발자-가이드" tabindex="-1">개발자 가이드 <a class="header-anchor" href="#개발자-가이드" aria-label="Permalink to “개발자 가이드”">​</a></h1><p>Lertaro 개발자 참조 매뉴얼에 오신 것을 환영합니다. Lertaro는 결합도 분리 다중 프로세스 아키텍처와 개방형 플러그인 생태계를 갖추고 있으며 공식 SDK 어셈블리 <code>Lertaro.PluginSdk</code>를 제공합니다. 개발자는 이 SDK를 참조하여 커스텀 검색 소스를 추가하고, 컨텍스트 액션 메뉴를 확장하며, 타사 파일 관리자 및 네이티브 대화상자와 연동하거나, 테마 및 파일 미리보기 핸들러를 자유롭게 구현할 수 있습니다.</p><h2 id="_1-아키텍처-및-개발-워크플로" tabindex="-1">1. 아키텍처 및 개발 워크플로 <a class="header-anchor" href="#_1-아키텍처-및-개발-워크플로" aria-label="Permalink to “1. 아키텍처 및 개발 워크플로”">​</a></h2><ul><li><strong><a href="./architecture.html">시스템 아키텍처 설계</a></strong> —— SYSTEM 권한 Windows 서비스, 사용자 모드 WPF UI, 키보드 후크 프로세스의 3 프로세스 격리 모델과 명명된 파이프 IPC 통신 구조.</li><li><strong><a href="./getting-started.html">빠른 시작 가이드</a></strong> —— 클래스 라이브러리 프로젝트 생성, SDK 참조, <code>IPlugin</code> 진입점 구현 및 로컬 디버깅 모범 사례.</li><li><strong><a href="./packaging.html">패키징 및 배포</a></strong> —— 어셈블리 디렉토리 구조 표준, 서드파티 관리/네이티브 DLL 패키징, 다국어 JSON 리소스 임베딩 및 PostBuild 자동 배포.</li><li><strong><a href="./examples.html">공식 플러그인 예제 분석</a></strong> —— 오픈소스로 제공되는 <code>CoreExtensions</code>, <code>PinyinAlias</code>, <code>FlowLauncherBridge</code>, <code>FileUnlocker</code> 플러그인의 실전 코드 분석.</li></ul><h2 id="_2-플러그인-sdk-api-레퍼런스" tabindex="-1">2. 플러그인 SDK API 레퍼런스 <a class="header-anchor" href="#_2-플러그인-sdk-api-레퍼런스" aria-label="Permalink to “2. 플러그인 SDK API 레퍼런스”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK 카테고리</th><th style="text-align:left;">핵심 인터페이스 및 서비스</th><th style="text-align:left;">주요 기능 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">검색 코어 및 액션</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">정적 인덱스 소스, 실시간 연산 응답, 비 ASCII 별칭 변환 엔진, 쿼리 접미사 토큰 핸들러 및 정적/동적 컨텍스트 액션 메뉴.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">시스템 및 대화상자 어댑터</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">활성 파일 탐색기 경로 감지, 네이티브 파일 대화상자 후킹, 인라인 검색바 내장 및 양방향 선택 동기화, 퀵 내비게이션 메뉴.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">UI 및 미리보기 확장</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">사이드바 필터 카테고리, 테이블 뷰 커스텀 열, 퀵 패널 동적 탭, QuickLook 커스텀 미리보기 렌더러, 썸네일 추출, WPF 테마 리소스 딕셔너리, i18n 언어 팩.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">공유 추상화 계약</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">검색 결과 읽기 전용 데이터 계약, 고정밀 파일 타임스탬프 및 크기 메타데이터, 호스트 윈도우 제어 핸들, 스키마 기반 네이티브 설정 폼.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">호스트 제공 서비스</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>MemoryMaintenanceService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">고성능 호스트 인프라: fzf 퍼지 매칭 및 하이라이트 마스크, 다국어 파싱, 캐싱 아이콘 추출, 즐겨찾기 관리/기록 조회, 디렉토리 인덱서 프록시, 지연 메모리 정리, 사용자 데이터 격리, Shell 네이티브 파일 작업.</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/notifications.html">알림</a></strong></td><td style="text-align:left;"><code>PluginNotificationService</code><br><code>NotificationRequest</code><br><code>INotificationHandle</code><br><code>NotificationLevel</code><br><code>NotificationPosition</code><br><code>NotificationResult</code><br><code>NotificationFailure</code></td><td style="text-align:left;">호스트 자신의 창을 통한 배경 알림: 오른쪽 아래 카드 더미 또는 하단 중앙의 한 줄 알림, 호스트가 잘라내는 표시 시간, <code>Id</code> 기반 대체, 플러그인별 제한, 반드시 끝나는 완료 작업.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>이 페이지들의 인터페이스 시그니처와 멤버명, 기본값, 매개변수 순서는 <code>Lertaro.PluginSdk</code> 소스에서 그대로 읽은 것입니다. 페이지가 플러그인 호출에 대한 <strong>호스트</strong>의 반응까지 설명하는 문장은 현재 동작의 기록일 뿐, 플러그인이 의존할 수 있는 계약이 아닙니다.</p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};